@@ -39,6 +39,7 @@ import org.apache.lucene.document.StoredField;
 import org.apache.lucene.document.StringField;
 import org.apache.lucene.geo.Circle;
 import org.apache.lucene.geo.Component2D;
+import org.apache.lucene.geo.GeoEncodingUtils;
 import org.apache.lucene.geo.GeoUtils;
 import org.apache.lucene.geo.LatLonGeometry;
 import org.apache.lucene.geo.Polygon;
@@ -390,6 +391,39 @@ public abstract class BaseGeoPointTestCase extends LuceneTestCase {
     dir.close();
   }

+  public void testNarrowPolygonCloseToNorthPole() throws Exception {
+    double minLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 3);
+    double maxLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE);
+    double minLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 3);
+    double maxLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE);
+    Polygon polygon =
+        new Polygon(
+            new double[] {minLat, minLat, maxLat, maxLat, minLat},
+            new double[] {minLon, maxLon, maxLon, minLon, minLon});
+
+    try (Directory dir = newDirectory();
+        IndexWriter writer = new IndexWriter(dir, newIndexWriterConfig())) {
+      Document inside = new Document();
+      addPointToDoc(
+          FIELD_NAME,
+          inside,
+          GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 2),
+          GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 2));
+      writer.addDocument(inside);
+      Document outside = new Document();
+      addPointToDoc(
+          FIELD_NAME,
+          outside,
+          GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 4),
+          GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 2));
+      writer.addDocument(outside);
+      try (IndexReader reader = DirectoryReader.open(writer)) {
+        IndexSearcher searcher = newSearcher(reader);
+        assertEquals(1, searcher.count(newPolygonQuery(FIELD_NAME, polygon)));
+        assertEquals(1, searcher.count(newGeometryQuery(FIELD_NAME, polygon)));
+      }
+    }
+  }
+
   /** test we can search for a polygon with a hole (but still includes the doc) */
   public void testPolygonHole() throws Exception {
     Directory dir = newDirectory();
PATCH

